def boss():
    def step(prompt, a, b, c, d, e=None):
        # Most steps pass a log string. A few omit it and pass choices next.
        if isinstance(a, str):
            log, choices, answer, why, keys = a, b, c, d, e
        elif isinstance(a, list) and isinstance(b, int):
            choices, answer = a, b
            log = "(No extra packet. Decide from the prompt and the last trace.)"
            if isinstance(d, list):
                why, keys = c, d
            elif isinstance(d, str) and isinstance(e, (list, tuple)):
                why, keys = f"{c} {d}", list(e)
            else:
                raise TypeError(f"bad step for {prompt!r}")
        else:
            raise TypeError(f"bad step for {prompt!r}")
        return {"prompt": prompt, "log": log, "choices": choices, "answer": answer, "why": why, "cites": cites(*keys)}
    return {"incidents": [
        {"id": "one-way", "title": "Caller hears silence after a carrier move", "summary": "The 200 OK is fine. The address in c= is not.",
         "epilogue": "Signaling health is not media health.",
         "steps": [
            step("The ladder completes. What do you open next?",
                 "SIP/2.0 200 OK\nCSeq: 1 INVITE\nContent-Type: application/sdp\nc=IN IP4 10.1.2.3\nm=audio 19642 RTP/AVP 0",
                 ["The c= line and whether 10.1.2.3 is reachable", "The To display name", "Max-Forwards", "The Allow header"],
                 0, "10.1.2.3 is not a public address. The phone will send RTP there and get nothing back.", ["3264", "3550"]),
            step("TLS is not in use on this hop. What else rewrites private addresses into SDP?",
                 "INVITE left the PBX with c=IN IP4 203.0.113.20\nThe carrier captured c=IN IP4 10.1.2.3",
                 ["A SIP ALG on the path", "RFC 4733", "A GRUU", "A session timer"],
                 0, "ALGs rewrite SDP and then fail when the rewritten address is useless.", ["3581"]),
            step("The fastest safe change is",
                 ["Anchor media on the SBC you control and disable the ALG", "Set Max-Forwards to 1", "Remove Contact", "Switch the codec to G.722 only"],
                 0, "Media anchoring gives the carrier a public address you own. The ALG has to go.", "Give the far end an address that routes, and stop the middlebox from editing SDP.", ["5853", "3264"]),
         ]},
        {"id": "codec-488", "title": "Every Webex call dies with 488", "summary": "The trunk is up. The offer has no codec the answerer will take.",
         "steps": [
            step("Where does 488 point?",
                 "SIP/2.0 488 Not Acceptable Here\nCSeq: 1 INVITE\nWarning: 304 example.com \"Media type not available\"",
                 ["This endpoint rejected the SDP offer", "DNS failed", "The registrar is down", "Max-Forwards hit zero"],
                 0, "488 is about this UA’s media, not about routing.", ["3261-21", "3264"]),
            step("The offer lists only G.729. The peer’s answer template lists PCMU and telephone-event. What is the overlap?",
                 "m=audio 49170 RTP/AVP 18\na=rtpmap:18 G729/8000",
                 ["No shared audio codec", "PCMU is implied by PT 18", "telephone-event is static PT 0", "The call should fall back inside RTP"],
                 0, "PT 18 is G.729 in the static table. It was not offered by the peer.", ["3551", "3264"]),
            step("What do you change?",
                 ["Add a shared codec, usually PCMU, on the SBC offer", "Delete Call-ID", "Send REGISTER", "Set the port to 0"],
                 0, "Port 0 would reject the stream on purpose. You need a shared encoding name.", "Offer a codec the peer actually answers.", ["3264", "webex-ios"]),
         ]},
        {"id": "options-tls", "title": "Teams marks the SBC inactive", "summary": "OPTIONS never completes. The certificate name and the Contact FQDN disagree.",
         "steps": [
            step("The admin center says inactive. What must succeed first?",
                 "SBC TLS connect to sip.pstnhub.microsoft.com:5061\nContact: <sip:203.0.113.20:5061;transport=tls>",
                 ["OPTIONS over TLS with 200 OK, and a Contact FQDN", "A UDP REGISTER to port 5060", "An RTP STUN binding", "A BYE"],
                 0, "Direct Routing health is OPTIONS, and an IP in Contact is refused.", ["teams-opts", "teams-sip"]),
            step("The certificate SAN is sbc1.example.com. The Contact host is 203.0.113.20. Microsoft’s rule is",
                 ["The FQDN in Contact must match the certificate name", "Any public IP is acceptable", "A self-signed certificate is preferred", "TLS 1.0 is required"],
                 0, "IP hosts are rejected with 403. The name has to be the one in the certificate.", ["teams-sip"]),
            step("TLS version on the SBC is 1.0. The troubleshooting article says",
                 ["Use TLS 1.2 or higher", "Disable TLS", "Use UDP 5060 to pstnhub", "Put the IP in Record-Route"],
                 0, "The documented requirement is TLS 1.2 or higher.", "Present the FQDN, a public certificate, and TLS 1.2, then confirm OPTIONS both ways.", ["teams-opts"]),
         ]},
        {"id": "fraud-spike", "title": "International minutes at 02:00", "summary": "A diagnostic, not a recipe. The source address was never on the trust list.",
         "steps": [
            step("The CDR export shows 200 calls to premium international destinations from one UDP source. First control to check?",
                 "show ip address trusted list\nSource 198.51.100.250 is not listed\nINVITE sip:90114415551212@203.0.113.20",
                 ["Whether that source is allowed to place VoIP calls", "The phone’s wallpaper", "RTCP jitter", "The SDP ptime"],
                 0, "IOS voice trusted-IP authentication is the documented toll-fraud control.", ["cme-toll"]),
            step("A dial-peer matches destination-pattern 9T and points at the carrier. The risk is",
                 ["Any caller who can reach the SBC can place outbound calls that match 9T", "9T blocks international", "T means TLS", "9T is a codec"],
                 0, "A wide pattern plus an open source list is the expensive combination.", ["cme-toll", "cube-basic"]),
            step("The defensive change is",
                 ["Trust only known peers and narrow outbound patterns", "Publish the SBC on 0.0.0.0/0 and hope", "Remove Max-Forwards", "Disable 200 OK"],
                 0, "Add the real peers to the trusted list. Do not open the list to every address.", "Restrict who may send INVITEs, then restrict what they may dial.", ["cme-toll", "srst-toll"]),
         ]},
        {"id": "timer-422", "title": "Calls drop at the same age", "summary": "Both sides want a refresh. They never agreed the interval.",
         "steps": [
            step("The second response is",
                 "SIP/2.0 422 Session Interval Too Small\nMin-SE: 1800\nCSeq: 1 INVITE",
                 ["The peer’s minimum session interval is higher than the offer", "The codec list is empty", "DNS SRV failed", "ICE consent expired"],
                 0, "422 and Min-SE are session timers.", ["4028"]),
            step("Who sends the refresh?",
                 "Session-Expires: 1800;refresher=uac",
                 ["The refresher parameter says which side", "Always the SBC", "Always the phone", "REFRESH is a SIP method"],
                 0, "refresher is uac or uas.", ["4028"]),
            step("A working retry uses",
                 ["Session-Expires at or above Min-SE", "Session-Expires: 1", "Remove Contact", "Port 0"],
                 0, "Raise the offered interval to the peer’s minimum and try again.", "Honor Min-SE. Do not loop 422 with the same value.", ["4028"]),
         ]},
        {"id": "delayed-offer", "title": "CUCM inserts an MTP and audio sounds like a tunnel", "summary": "The INVITE left without SDP. Something on the trunk demanded an MTP.",
         "steps": [
            step("This INVITE is",
                 "INVITE sip:+15551212@198.51.100.30 SIP/2.0\nContent-Length: 0",
                 ["Delayed offer", "Early offer", "A REGISTER", "An ACK"],
                 0, "No SDP in the INVITE means the offer is not here.", ["3264"]),
            step("CUCM may add an MTP when the trunk requires one. The lab’s advice is",
                 ["Read the CUCM trunk guide for that version before assuming the checkbox", "Always set MTP required", "Delete the SIP trunk", "Disable SDP"],
                 0, "MTP required is real, and the exact UI belongs to the version’s admin guide.", ["cucm"]),
            step("If the carrier needs early offer, the CUBE knob documented for that is",
                 ["voice-class sip early-offer forced on the outbound dial-peer", "no sip", "codec g729 only with no offer", "Max-Forwards 0"],
                 0, "early-offer forced is the CUBE mechanism. Confirm it in the configuration guide.", "Decide which hop is allowed to delay the offer, and force early offer only where the peer requires it.", ["cube-basic", "3264"]),
         ]},
        {"id": "too-many-hops", "title": "483 after a routing loop", "summary": "Two proxies keep sending the request to each other.",
         "steps": [
            step("The response is 483 Too Many Hops. The header that ran out is",
                 "SIP/2.0 483 Too Many Hops\nCSeq: 1 INVITE",
                 ["Max-Forwards", "Content-Length", "ptime", "SSRC"],
                 0, "Each hop decrements Max-Forwards. Zero becomes 483.", ["3261-8.1.1.6"]),
            step("The Record-Route set shows the same two proxies alternating. That means",
                 ["A routing loop, not a codec problem", "SRTP is disabled", "The phone is on hold", "ICE failed"],
                 0, "Look at Route and the request URI, not the m-line.", ["3261-16"]),
            step("The fix is",
                 ["Correct the route so the request leaves the loop", "Raise Max-Forwards to 1000 and keep the loop", "Remove To tags", "Add a second Call-ID"],
                 0, "A higher Max-Forwards only delays the failure.", "Break the loop in the dial plan or Route set.", ["3261-16"]),
         ]},
        {"id": "diversion", "title": "Unity plays the wrong greeting", "summary": "The forwarded-from number never arrived.",
         "steps": [
            step("The PBX sent Diversion. The SBC’s outbound INVITE has no Diversion and no History-Info. Unity keys the greeting from",
                 "INVITE sip:voicemail@198.51.100.40 SIP/2.0\nTo: <sip:+15551212@example.com>\n(no Diversion, no History-Info)",
                 ["The original called number, which is now missing", "The RTP SSRC", "The branch cookie", "ptime"],
                 0, "Diversion is widely used and is not the standards-track history mechanism. History-Info is.", ["5806", "7044"]),
            step("A CUBE teaching rule that deletes every Diversion looks like",
                 "request INVITE sip-header Diversion remove",
                 ["That rule explains the missing header", "That rule adds PAI", "That rule forces early offer", "That rule is an RTP command"],
                 0, "remove drops the header on the way out.", ["cube-prof"]),
            step("The interop choice is",
                 ["Pass Diversion or map it to History-Info on purpose", "Always delete both", "Replace them with Server", "Strip Contact"],
                 0, "Decide the history header the voicemail system documents, and keep that one.", "Restore the header the voicemail integration guide names.", ["unity", "7044"]),
         ]},
    ]}


def interview():
    items = [
        ("Core", "What identifies a SIP dialog?", "Call-ID plus the From tag and the To tag.", "3261-12"),
        ("Core", "What identifies a transaction on a hop?", "The Via branch parameter. In RFC 3261 it starts with z9hG4bK.", "3261-8.1.1.7"),
        ("Core", "Why are there two kinds of ACK?", "A 2xx ACK is its own end-to-end transaction. A non-2xx ACK belongs to the INVITE transaction and is hop-by-hop. RFC 6026 tightens the 2xx rules.", "6026"),
        ("Core", "What is the recommended initial Max-Forwards?", "70.", "3261-8.1.1.6"),
        ("Core", "What does 100 Trying mean?", "The next hop has the INVITE and the previous hop can stop retransmitting. It does not mean the phone is ringing.", "3261-21"),
        ("Core", "Name the compact form of Contact, To, From, and Via.", "m, t, f, and v.", "3261-20"),
        ("Core", "What is the difference between 401 and 407?", "401 is the UAS challenge and uses Authorization. 407 is the proxy challenge and uses Proxy-Authorization.", "3261-22"),
        ("Core", "What creates a registration binding?", "REGISTER, with Contact and an expiration. The registrar stores the binding.", "3261-10"),
        ("Core", "What is 423?", "Interval Too Brief. The registrar wants a longer Expires.", "3261-10"),
        ("Core", "What does RFC 3263 add?", "How to find a SIP server with NAPTR, SRV, and address records.", "3263"),
        ("Media", "Which RFC is the current SDP specification?", "RFC 8866, which obsoletes RFC 4566.", "8866"),
        ("Media", "How must an answer line up with an offer?", "Same number of m-lines, same order. Port 0 rejects a stream.", "3264"),
        ("Media", "How do you match dynamic payload types?", "By the encoding name in rtpmap, not by the payload type number.", "3264"),
        ("Media", "What is strange about G.722 in rtpmap?", "RFC 3551 uses clock rate 8000 even though the audio is 16 kHz.", "3551"),
        ("Media", "Where do DTMF events belong if you follow the IETF media spec?", "In RTP as telephone-event, RFC 4733. SIP INFO is a different mechanism.", "4733"),
        ("Media", "What does a=sendonly mean for hold?", "The offerer will send and not receive. The answerer should reply recvonly or inactive.", "3264-6"),
        ("Media", "What is in an RTP packet that a capture uses to spot loss?", "The sequence number. RTCP reports the loss fraction.", "3550"),
        ("Media", "Name two SRTP keying styles and their RFCs.", "SDES, RFC 4568, puts keys in SDP. DTLS-SRTP, RFC 5764, keys in the media path. SRTP itself is RFC 3711.", "3711"),
        ("Media", "What is early media?", "Media before the call is answered. RFC 3960 discusses it. 183 with SDP is the common signal, not a guarantee.", "3960"),
        ("NAT", "Why do NATs break SIP?", "SIP and SDP name IP addresses and ports that the NAT does not know to rewrite consistently.", "3581"),
        ("NAT", "What does rport do?", "It asks the peer to send the response to the source port it observed.", "3581"),
        ("NAT", "Which RFC is current for ICE, STUN, and TURN?", "ICE is RFC 8445, STUN is RFC 8489, TURN is RFC 8656.", "8445"),
        ("NAT", "What is a relay candidate?", "An address allocated on a TURN server.", "8656"),
        ("NAT", "Why is a SIP ALG dangerous?", "It rewrites signaling or SDP in transit, often to a useless address, and it cannot see inside TLS.", "5853"),
        ("Security", "Is P-Asserted-Identity cryptographic?", "No. RFC 3325 is an assertion inside a trust domain. STIR, RFC 8224, is the cryptographic identity.", "3325"),
        ("Security", "What token does STIR carry?", "A PASSporT, RFC 8225.", "8225"),
        ("Security", "Where are SHAKEN attestation rules published?", "In ATIS SHAKEN specifications. The FCC call-authentication page is the regulator’s overview. Do not quote an attestation letter from memory without the current ATIS text.", "fcc-stir"),
        ("SBC", "Is there an SBC protocol RFC?", "No. RFC 5853 records requirements. The device is usually a B2BUA, RFC 7092.", "5853"),
        ("SBC", "What is topology hiding?", "Rewriting the signaling so the inside addresses and headers are not shown to the outside. It is a B2BUA behavior.", "7092"),
        ("Cisco", "What does debug ccsip messages show?", "SIP messages the IOS voice stack sent and received.", "cube-basic"),
        ("Cisco", "How does a CUBE SIP profile differ from a CUCM SIP Profile?", "CUBE voice class sip-profiles is a header rewrite list. A CUCM SIP Profile is a trunk settings object.", "cube-prof"),
        ("Cisco", "What is early-offer forced?", "A CUBE dial-peer setting that sends the SDP offer in the outbound INVITE.", "cube-basic"),
        ("Cisco", "What does the IOS trusted IP list prevent?", "VoIP call setups from addresses that are not trusted. It is the documented toll-fraud control. Confirm the list size in the guide for your platform.", "cme-toll"),
        ("Cloud", "Which three names does Direct Routing publish for SIP?", "sip.pstnhub.microsoft.com, sip2.pstnhub.microsoft.com, and sip3.pstnhub.microsoft.com, port 5061.", "teams-plan"),
        ("Cloud", "Why does Teams reject a Contact that contains an IP address?", "Direct Routing requires the SBC FQDN in Contact, matching the certificate. An IP is refused with 403.", "teams-sip"),
        ("Cloud", "How is Webex premises PSTN different from Cloud Connected PSTN?", "Premises PSTN uses your Local Gateway and carrier. Cloud Connected PSTN is a cloud partner. A location uses one of them.", "webex-org"),
        ("Cloud", "Does Amazon Connect need a SIP trunk for ordinary PSTN calls?", "No. Connect provides the voice channel. External SIPREC into a connector is a different feature. Chime Voice Connector is not a supported shortcut into Connect without a specialist review.", "connect-tel"),
        ("Cloud", "What is Twilio termination versus origination?", "Termination is your system calling the PSTN. Origination is the PSTN calling your system. The Request-URI on termination must reference the trunk’s termination URI.", "twilio-ts"),
        ("Design", "What do you agree before you turn up a carrier trunk?", "Transport and certificates, codecs including telephone-event, E.164 format, which side offers, SRTP keying, trusted addresses, and OPTIONS.", "3261"),
        ("Design", "What is the first question in a one-way-audio ticket?", "Did signaling complete, and which address and port does each SDP name?", "3550"),
    ]
    return {"items": [{"level": level, "q": q, "a": a, "cites": cites(key)} for level, q, a, key in items]}


